```ts
interface ChatMediator {
  send(message: string, from: User): void;
  register(user: User): void;
}

class ChatRoom implements ChatMediator {
  private users: User[] = [];
  register(user: User) { this.users.push(user); }
  send(message: string, from: User) {
    for (const u of this.users) {
      if (u !== from) u.receive(message, from.name);
    }
  }
}

class User {
  constructor(public name: string, private room: ChatMediator) {
    room.register(this);
  }
  send(message: string) { this.room.send(message, this); }
  receive(message: string, from: string) { console.log(`${from}: ${message}`); }
}

const room = new ChatRoom();
const alice = new User('Alice', room);
const bob = new User('Bob', room);
alice.send('hey Bob');   // Alice never holds a reference to Bob directly
```

`User` only ever calls methods on `ChatMediator` — it has no idea how many other users exist or how messages actually get routed to them.

```ts
class EditorMemento {
  constructor(private readonly content: string) {}
  // only Editor knows this exists / how to use it meaningfully
  getContent(): string { return this.content; }
}

class Editor {
  private content = '';
  type(text: string) { this.content += text; }
  save(): EditorMemento { return new EditorMemento(this.content); }
  restore(m: EditorMemento) { this.content = m.getContent(); }
}

class History {
  private snapshots: EditorMemento[] = [];
  push(m: EditorMemento) { this.snapshots.push(m); }
  pop(): EditorMemento | undefined { return this.snapshots.pop(); }
}

const editor = new Editor();
const history = new History();
editor.type('Hello');
history.push(editor.save());
editor.type(' World');
editor.restore(history.pop()!);   // back to 'Hello', History never read the content itself
```

`History` stores and hands back `EditorMemento` objects but never calls `getContent()` on them — only `Editor` ever meaningfully interprets what's inside a memento it created itself.
